<script lang="ts">
 import {invalidateAll} from '$app/navigation';
 let {model,t,owner}:{model:Record<string,Record<string,any>[]>;t:(s:string)=>string;owner:boolean}=$props();let id=$state(''),name=$state(''),adapter=$state('file'),enabled=$state(false),apiKey=$state(''),uid=$state(''),apiUser=$state(''),apiCode=$state(''),shop=$state('1'),aiModel=$state(''),embeddingModel=$state(''),daily=$state(20),tokens=$state(1000),dataConsent=$state(false),costConsent=$state(false),wineAuthority=$state('app'),bottleAuthority=$state('app'),baseUrl=$state(''),path=$state(''),source=$state(''),confirmed=$state(false),writeEnabled=$state(false),writePath=$state(''),reconcilePath=$state(''),writeConfirmed=$state(false),busy=$state(false),message=$state(''),result=$state<any>(null);
 function choose(){const c=model.connections.find(c=>c.id===id);if(!c)return;name=c.name;adapter=c.adapter;enabled=c.enabled;wineAuthority=c.authority.wine;bottleAuthority=c.authority.bottles;aiModel=c.configuration?.model??'';embeddingModel=c.configuration?.embedding_model??'';daily=c.configuration?.daily_requests??20;tokens=c.configuration?.max_output_tokens??1000;dataConsent=c.configuration?.data_consent??false;costConsent=c.configuration?.cost_consent??false;baseUrl=c.configuration?.contract?.base_url??'';path=c.configuration?.contract?.path??'';source=c.configuration?.contract?.source??'';confirmed=c.configuration?.contract?.confirmed??false;writeEnabled=Boolean(c.configuration?.contract?.outbound);writePath=c.configuration?.contract?.outbound?.path??'';reconcilePath=c.configuration?.contract?.outbound?.reconcile_path??'';writeConfirmed=Boolean(c.configuration?.contract?.outbound?.confirmed);apiKey='';uid='';apiUser='';apiCode='';}
 async function save(){busy=true;message='';try{const existing=model.connections.find(c=>c.id===id);const configuration={embedding_model:embeddingModel||undefined,model:aiModel||undefined,daily_requests:daily,max_output_tokens:tokens,data_consent:dataConsent,cost_consent:costConsent,...(['vintrace','contract-api'].includes(adapter)?{contract:{base_url:baseUrl,path,source,method:'GET',confirmed,...(adapter==='contract-api'&&writeEnabled?{outbound:{path:writePath,reconcile_path:reconcilePath,idempotency:writeConfirmed,confirmed:writeConfirmed}}:{})}}:{})};const body={id:id||undefined,expected_version:existing?.version,name,adapter,enabled,configuration,authority:{wine:wineAuthority,bottles:bottleAuthority},credentials:{api_key:apiKey||undefined,UID:uid||undefined,apiUSER:apiUser||undefined,apiCODE:apiCode||undefined,apiShopID:shop}};if(adapter!=='winestro')delete (body.credentials as any).apiShopID;const res=await fetch('/api/connections',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const json=await res.json();message=res.ok?t('saved'):t(json.message);if(res.ok){id=json.id;apiKey='';apiCode='';uid='';apiUser='';await invalidateAll();}}catch{message=t('connectionError');}finally{busy=false;}}
 async function sync(cid:string){busy=true;try{const res=await fetch('/api/connections/sync',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({connection_id:cid})});result=await res.json();message=res.ok?t('saved'):t(result.message);if(res.ok)await invalidateAll();}finally{busy=false;}}
 function download(){const blob=new Blob([JSON.stringify(result.data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='erp-import.json';a.click();URL.revokeObjectURL(url);}
</script>
<section class="card"><h2>{t('connections')}</h2><p class="muted">{t('connectionsHint')}</p>{#each model.connections as c}<div class="connection"><span>{c.name} · {c.adapter} · {t(c.enabled?'active':'disabled')}</span>{#if c.enabled&&['winestro','vintrace','contract-api','openai-compatible'].includes(c.adapter)}<button onclick={()=>sync(c.id)} disabled={busy}>{t('readConnection')}</button>{/if}</div>{/each}{#if result?.data}<details open><summary>{t('remoteSnapshot')}</summary><p class="muted">{t('remoteSnapshotHint')}</p><pre>{JSON.stringify(result.data,null,2).slice(0,15000)}</pre><button onclick={download}>{t('download')} JSON</button></details>{/if}{#if owner}<details><summary>{t('configureConnection')}</summary><form onsubmit={(e)=>{e.preventDefault();save();}}><label>{t('connections')}<select bind:value={id} onchange={choose}><option value="">{t('newConnection')}</option>{#each model.connections as c}<option value={c.id}>{c.name}</option>{/each}</select></label><div class="grid"><label>{t('name')}<input bind:value={name} required maxlength="160" /></label><label>{t('provider')}<select bind:value={adapter}>{#each ['file','winestro','vintrace','contract-api','openai-compatible','brightsky','sensor'] as provider}<option value={provider}>{provider==='openai-compatible'?'OpenAI':provider==='file'?'CSV / JSON / XLSX':provider}</option>{/each}</select></label></div><label class="check"><input type="checkbox" bind:checked={enabled} />{t('enabled')}</label>{#if adapter==='winestro'}<p class="muted">{t('winestroScope')}</p><a href="https://nephele-s5.de/xml/docs/xml_22.0.php" target="_blank" rel="noreferrer">API v22</a><div class="grid"><label>UID<input bind:value={uid} autocomplete="off" /></label><label>API User<input bind:value={apiUser} autocomplete="off" /></label><label>API Code<input type="password" bind:value={apiCode} autocomplete="new-password" /></label><label>Shop ID<input bind:value={shop} /></label></div>{:else if ['vintrace','contract-api','openai-compatible'].includes(adapter)}<label>API Key<input type="password" bind:value={apiKey} autocomplete="new-password" /></label><p class="muted">{t('keepSecret')}</p>{/if}{#if ['vintrace','contract-api'].includes(adapter)}<div class="grid"><label>API URL<input bind:value={baseUrl} type="url" required /></label><label>GET {t('endpoint')}<input bind:value={path} required /></label><label>{t('source')}<input bind:value={source} type="url" required /></label></div><label class="check"><input type="checkbox" bind:checked={confirmed} required />{t('confirmContract')}</label>{/if}{#if adapter==='contract-api'}<label class="check"><input type="checkbox" bind:checked={writeEnabled} />{t('outboundERP')}</label>{#if writeEnabled}<p class="muted">{t('contractReceiptHint')}</p><div class="grid"><label>POST {t('endpoint')}<input required bind:value={writePath} /></label><label>GET {t('reconcile')}<input required bind:value={reconcilePath} /></label></div><label class="check"><input type="checkbox" required bind:checked={writeConfirmed} />{t('confirmWriteContract')}</label>{/if}{/if}{#if adapter==='openai-compatible'}<div class="grid"><label>{t('aiModel')}<input bind:value={aiModel} required /></label><label>{t('embeddingModel')}<select bind:value={embeddingModel}><option value="">{t('disabled')}</option><option>text-embedding-3-small</option><option>text-embedding-3-large</option></select></label><label>{t('dailyRequests')}<input type="number" bind:value={daily} min="1" max="500" /></label><label>{t('outputTokens')}<input type="number" bind:value={tokens} min="100" max="4000" /></label></div><p class="muted">{t('aiCosts')}</p><label class="check"><input type="checkbox" bind:checked={dataConsent} />{t('aiDataConsent')}</label><label class="check"><input type="checkbox" bind:checked={costConsent} />{t('aiCostConsent')}</label>{/if}<div class="grid"><label>{t('wineAuthority')}<select bind:value={wineAuthority}><option value="app">Vinea</option><option value="erp">ERP</option></select></label><label>{t('bottleAuthority')}<select bind:value={bottleAuthority}><option value="app">Vinea</option><option value="erp">ERP</option></select></label></div><p class="muted">{t('authorityHint')}</p><button disabled={busy}>{t('save')}</button></form></details>{/if}<p role="status">{message}</p></section>
<style>.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;margin:15px 0}.check{display:flex;align-items:center;margin:16px 0}.check input{width:18px;height:18px}.connection{display:flex;justify-content:space-between;align-items:center;gap:15px;border-bottom:1px solid #e1e7de;padding:12px 0}form{margin:20px 0}pre{overflow:auto;max-height:350px;font-size:11px}summary{cursor:pointer;margin:18px 0}</style>
